-- Generated by scripts/build_compiled.py from src/fraudrules/rules/money-mule/mu-004-p2p-in-cash-out.yaml. Do not edit.
-- MU-004 P2P credits from several people followed by a cash withdrawal
SELECT 'MU-004' AS rule_id, 'transactions' AS anchor_table, a.id AS anchor_id
FROM transactions AS a
JOIN transactions AS b ON b.account_id = a.account_id AND b.ts <= a.ts AND b.ts > a.ts - 259200
WHERE (a.direction = 'out' AND a.channel IN ('cash', 'atm')) AND (b.direction = 'in' AND b.channel = 'p2p')
GROUP BY a.id
HAVING (COUNT(DISTINCT b.counterparty_id) >= 3 AND MAX(a.amount_cents) * 100 >= SUM(b.amount_cents) * 70);
